<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Rashan Cart Admin</title>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<script src="https://cdn.tailwindcss.com/3.4.17"></script>
<script>tailwind.config={theme:{extend:{colors:{bg:'var(--bg)',sf:'var(--sf)',tx:'var(--tx)',mu:'var(--mu)',bd:'var(--bd)',br:'var(--br)',bs:'var(--bs)',bt:'var(--bt)'}}}}</script>
<style>
:root{box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);--bg:#f6fdf9;--sf:#ffffff;--tx:#14261c;--mu:#6b8576;--bd:#e3f3ea;--br:#5fdc93;--bt:#168f4d;--bs:#e7faef;--c2:#f5b83d;--sh:0 1px 2px rgba(20,38,28,.03),0 10px 28px -14px rgba(95,220,147,.3);color-scheme:light}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0b1410;--sf:#111c16;--tx:#e8f3ec;--mu:#8fa99a;--bd:#213128;--br:#4ade80;--bt:#6ee7a0;--bs:#153a27;--sh:none;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#0b1410;--sf:#111c16;--tx:#e8f3ec;--mu:#8fa99a;--bd:#213128;--br:#4ade80;--bt:#6ee7a0;--bs:#153a27;--sh:none;color-scheme:dark}
html{scroll-padding-top:env(safe-area-inset-top,0px)}
body{background:var(--bg);color:var(--tx);font-family:"Plus Jakarta Sans",system-ui,-apple-system,"Segoe UI",sans-serif}
.side{background:var(--sf);border-right:1px solid var(--bd)}
.card{background:var(--sf);border:1px solid var(--bd);border-radius:18px;box-shadow:var(--sh)}
.btn{border:1px solid var(--bd);border-radius:10px;padding:6px 12px;font-size:12px;font-weight:600;background:var(--sf);white-space:nowrap}
.btn:hover{border-color:var(--br)}
.btn-p{background:var(--br);border-color:var(--br);color:#06301a}
.nav{display:flex;gap:10px;align-items:center;padding:9px 12px;border-radius:11px;font-size:14px;font-weight:500;color:var(--mu);width:100%;text-align:left}
.nav:hover{background:var(--bg)}
.nav.on{background:var(--bs);color:var(--bt);font-weight:600}
.chip{padding:5px 12px;border-radius:999px;font-size:12px;font-weight:600;color:var(--mu);border:1px solid var(--bd);white-space:nowrap}
.chip.on{background:var(--tx);color:var(--sf);border-color:var(--tx)}
th{text-align:left;font-weight:500;color:var(--mu);font-size:12px;padding:8px 14px}
td{padding:12px 14px;border-top:1px solid var(--bd);font-size:13px;white-space:nowrap}
tbody tr:hover{background:var(--bg)}
input,select{background:var(--sf);color:var(--tx);border:1px solid var(--bd);border-radius:10px;padding:8px 12px;font-size:13px;outline:none;width:100%}
input:focus,select:focus{border-color:var(--br)}
.pop{animation:pop .18s ease-out}@keyframes pop{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.pop{animation:none}}
</style>
</head>
<body>
<div class="flex min-h-screen">
  <aside class="side hidden lg:flex w-64 shrink-0 flex-col p-4 sticky top-0 h-screen">
    <div class="flex items-center gap-2.5 px-2 pb-6"><div class="w-9 h-9 rounded-xl bg-br text-[#06301a] grid place-items-center font-bold">R</div><div><p class="font-bold leading-none">Rashan Cart</p><p class="text-xs text-mu mt-1">Admin console</p></div></div>
    <nav id="nav" class="flex flex-col gap-1 overflow-y-auto min-h-0 flex-1"></nav>
    <div class="mt-3 rounded-2xl bg-bs p-4"><p class="text-sm font-semibold" style="color:var(--bt)">Bulk window closes soon</p><p class="text-xs text-mu mt-1">2 campaigns hit their target and are waiting for a purchase order.</p><button class="btn btn-p mt-3 w-full" onclick="go('campaigns')">Review campaigns</button></div>
  </aside>
  <main class="flex-1 min-w-0">
    <header class="sticky top-0 z-20 px-4 md:px-8 py-3 flex items-center gap-3 border-b border-bd" style="background:var(--bg)">
      <div class="relative flex-1 max-w-md"><span class="absolute left-3 top-1/2 -translate-y-1/2 text-mu" id="ics"></span><input id="gs" placeholder="Search orders (press /)" style="padding-left:36px" oninput="gsearch(this.value)" aria-label="Search"></div>
      <div class="ml-auto flex items-center gap-2 relative">
        <button class="btn" id="th">Theme</button>
        <button class="btn !p-2" onclick="$('#np').classList.toggle('hidden')" aria-label="Notifications"><span id="icb"></span></button>
        <div id="np" class="hidden pop absolute right-0 top-11 w-72 card p-3 z-30"></div>
        <div class="w-9 h-9 rounded-full bg-br text-[#06301a] grid place-items-center text-sm font-bold">AD</div>
      </div>
    </header>
    <div id="mnav" class="lg:hidden flex gap-1 overflow-x-auto px-4 pt-3"></div>
    <div id="view" class="p-4 md:p-8 max-w-[1280px] mx-auto"></div>
  </main>
</div>
<div id="toast" class="fixed bottom-5 right-5 z-50"></div>
<div id="modal"></div>

@verbatim
<script>
const $=s=>document.querySelector(s);
const P={home:'M3 11l9-8 9 8v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',mega:'M3 11v2a1 1 0 0 0 1 1h2l5 4V6L6 10H4a1 1 0 0 0-1 1zM16 8a5 5 0 0 1 0 8',cart:'M3 4h2l2.5 11h10L20 7H6.5M9 20h.01M17 20h.01',bld:'M4 21V5a1 1 0 0 1 1-1h8a1 1 0 0 1 1 1v16M14 10h5a1 1 0 0 1 1 1v10M2 21h20M8 8h2M8 12h2M8 16h2',box:'M21 8l-9-5-9 5v8l9 5 9-5zM3 8l9 5 9-5M12 13v8',truck:'M2 6h11v10H2zM13 9h4l4 4v3h-8M6 19h.01M17 19h.01',chart:'M4 20V10M10 20V4M16 20v-8M22 20H2',bell:'M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9M10 21h4',search:'M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16M21 21l-4.3-4.3',plus:'M12 5v14M5 12h14',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8',tag:'M20.6 13.4l-7.2 7.2a2 2 0 0 1-2.8 0L2 12V2h10l8.6 8.6a2 2 0 0 1 0 2.8zM7 7h.01',card:'M2 5h20v14H2zM2 10h20',pin:'M12 22s7-6.2 7-12a7 7 0 1 0-14 0c0 5.8 7 12 7 12zM12 12.5a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5',set:'M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M1 14h6M9 8h6M17 16h6'};
const ic=(n,c='w-[18px] h-[18px]')=>`<svg class="${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${P[n]}"/></svg>`;
const badge=(t,c='g')=>{const m={g:'#10b981',a:'#f59e0b',r:'#f43f5e',b:'#3b82f6',x:'#8b95a5'}[c];return `<span style="color:${m};background:${m}22" class="text-xs font-semibold px-2.5 py-1 rounded-full">${t}</span>`};
const prog=(p,c='var(--br)')=>`<div class="h-2 rounded-full bg-bd overflow-hidden min-w-[90px]"><div class="h-full rounded-full" style="width:${Math.min(100,p)}%;background:${c}"></div></div>`;
const card=(t,b,a='',x='')=>`<section class="card p-5 ${x}"><div class="flex items-center justify-between gap-2 mb-4"><h2 class="font-semibold">${t}</h2>${a}</div>${b}</section>`;
const table=(h,r,id='')=>`<div class="overflow-x-auto -mx-2"><table class="w-full"><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody ${id?`id="${id}"`:''}>${r.join?r.map(x=>`<tr>${x.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):''}</tbody></table></div>`;
const head=(t,s,a='')=>`<div class="flex flex-wrap items-end justify-between gap-3 mb-6"><div><h1 class="text-2xl font-bold tracking-tight">${t}</h1><p class="text-sm text-mu mt-1">${s}</p></div><div class="flex gap-2 items-center">${a}</div></div>`;
const toast=m=>{$('#toast').innerHTML=`<div class="pop card px-4 py-3 text-sm font-semibold">${m}</div>`;clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').innerHTML='',2600)};

const S={view:'dashboard',range:'30d',of:'All',q:'',
camps:[{n:'Basmati rice 5 kg',h:'Block 7',j:100,t:100,d:'Oct 26',s:'Open'},{n:'Fresh eggs, 30 tray',h:'Block 9',j:120,t:120,d:'Oct 25',s:'Open'},{n:'Cooking oil 5 L',h:'Block 11',j:47,t:80,d:'Oct 28',s:'Open'},{n:'Wheat flour 10 kg',h:'Block 7',j:22,t:60,d:'Oct 30',s:'Open'},{n:'Pulses bundle',h:'Block 3',j:64,t:70,d:'Oct 29',s:'Open'},{n:'Sugar 5 kg',h:'Block 9',j:90,t:90,d:'Oct 20',s:'Ordered'}],
stock:[['Cooking oil 5 L',12,40,'Al-Noor Traders'],['Wheat flour 10 kg',9,30,'City Wholesale'],['Pulses bundle',6,25,'Metro Foods'],['Basmati rice 5 kg',88,50,'Al-Noor Traders'],['Fresh eggs, 30 tray',64,60,'Farm Fresh Co.'],['Sugar 5 kg',70,40,'City Wholesale']],
orders:[['#1088','Ayesha Khan','Rice, oil, eggs','Rs 42.10','Delivering','Block 7'],['#1087','Bilal Ahmed','Flour 10 kg','Rs 8.40','Pending','Block 9'],['#1086','Sana Malik','Eggs x2','Rs 10.20','Delivered','Block 9'],['#1085','Omar Farooq','Pulses, sugar','Rs 19.70','Delivered','Block 3'],['#1084','Hina Raza','Oil 5 L','Rs 13.90','Refund','Block 11'],['#1083','Zain Ali','Rice x2','Rs 22.40','Delivering','Block 7'],['#1082','Maryam Iqbal','Sugar, flour','Rs 17.60','Pending','Block 9'],['#1081','Usman Tariq','Eggs, oil','Rs 19.00','Delivered','Block 11']],
sup:[['Al-Noor Traders',4.8,96,'Rice, oil','Rs 10.80'],['City Wholesale',4.5,91,'Flour, sugar','Rs 11.30'],['Metro Foods',4.6,94,'Pulses, dairy','Rs 11.90'],['Farm Fresh Co.',4.7,98,'Eggs, produce','Rs 4.90']],
riders:[['Imran Siddiqui','Blocks 7 to 9',14,18,1],['Kamran Ali','Blocks 3 to 5',11,15,2],['Saad Mehmood','Blocks 10 to 12',9,16,2]]};
const sc={Delivered:'g',Delivering:'b',Pending:'a',Refund:'r'};
const st=c=>c.s=='Open'&&c.j>=c.t?'Ready':c.s;
const stc={Ready:'g',Open:'b',Ordered:'x',Closed:'x'};
const NAV=[['dashboard','Dashboard','home','Overview'],['campaigns','Campaigns','mega','Overview'],['orders','Orders','cart','Overview'],['products','Products','tag','Operations'],['suppliers','Suppliers','bld','Operations'],['inventory','Inventory','box','Operations'],['deliveries','Deliveries','truck','Operations'],['customers','Customers','users','Business'],['payments','Payments','card','Business'],['neighborhoods','Neighborhoods','pin','Business'],['reports','Reports','chart','Business'],['settings','Settings','set','System']];

/* charts */
const spark=v=>{const m=Math.max(...v),n=Math.min(...v),w=90,h=30;const pts=v.map((x,i)=>`${i*w/(v.length-1)},${h-2-(x-n)/(m-n||1)*(h-6)}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" class="w-24 h-8"><polyline points="${pts}" fill="none" stroke="var(--br)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`};
const area=(series,labels)=>{const W=640,H=230,Pd=34,max=Math.ceil(Math.max(...series[0].v,...series[1].v)),n=labels.length;
 const X=i=>Pd+i*(W-Pd-10)/(n-1),Y=v=>H-26-v/max*(H-26-12);
 const path=v=>v.map((y,i)=>i?`C${(X(i-1)+X(i))/2},${Y(v[i-1])} ${(X(i-1)+X(i))/2},${Y(y)} ${X(i)},${Y(y)}`:`M${X(0)},${Y(y)}`).join(' ');
 let g='';for(let k=0;k<=4;k++){const val=max*k/4;g+=`<line x1="${Pd}" x2="${W-10}" y1="${Y(val)}" y2="${Y(val)}" stroke="var(--bd)"/><text x="0" y="${Y(val)+4}" font-size="10" fill="var(--mu)">Rs ${val.toFixed(0)}k</text>`}
 return `<svg viewBox="0 0 ${W} ${H}" class="w-full">${g}${series.map((s,i)=>`<path d="${path(s.v)} L${X(n-1)},${Y(0)} L${X(0)},${Y(0)}Z" fill="${s.c}" opacity=".${i?'07':'12'}"/><path d="${path(s.v)}" fill="none" stroke="${s.c}" stroke-width="2.5" stroke-linecap="round"/>`).join('')}${labels.map((l,i)=>`<text x="${X(i)}" y="${H-6}" font-size="10" text-anchor="middle" fill="var(--mu)">${l}</text>`).join('')}</svg>`};
const bars=(v,l,suf='')=>{const m=Math.max(...v);return `<div class="flex items-end gap-3 h-48">${v.map((x,i)=>`<div class="flex-1 h-full flex flex-col justify-end items-center gap-1"><span class="text-[11px] text-mu">${x}${suf}</span><div class="w-full rounded-t-lg" style="height:${x/m*78}%;background:var(--br);opacity:${i==v.length-1?1:.5}"></div><span class="text-[11px] text-mu">${l[i]}</span></div>`).join('')}</div>`};
const donut=(d)=>{let a=0;const cols=['#5fdc93','#b7efcf','#2dd4bf','#f5b83d','#94a3b8'];const g=d.map((x,i)=>{const s=`${cols[i]} ${a}% ${a+x[1]}%`;a+=x[1];return s}).join(',');
 return `<div class="flex items-center gap-5 flex-wrap"><div class="relative w-36 h-36 rounded-full shrink-0" style="background:conic-gradient(${g})"><div class="absolute inset-[22px] rounded-full bg-sf grid place-items-center text-center"><div><p class="text-lg font-bold">Rs 38.2k</p><p class="text-[11px] text-mu">Sales</p></div></div></div><div class="space-y-2 text-sm">${d.map((x,i)=>`<div class="flex items-center gap-2"><span class="w-2.5 h-2.5 rounded-full" style="background:${cols[i]}"></span>${x[0]}<span class="text-mu ml-auto pl-4">${x[1]}%</span></div>`).join('')}</div></div>`};

const RG={'7d':{m:.24,l:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],r:[1.1,1.5,1.3,1.8,1.6,2.1,1.9],c:[.9,1.2,1.1,1.4,1.3,1.6,1.5]},'30d':{m:1,l:['1','4','7','10','13','16','19','22','25','28'],r:[3.1,3.6,3.4,4.2,3.9,4.6,4.4,5.1,4.8,5.6],c:[2.6,3,2.9,3.4,3.3,3.7,3.6,4.1,3.9,4.4]},'90d':{m:2.95,l:['W1','W2','W3','W4','W5','W6','W7','W8','W9','W10','W11','W12'],r:[2.8,3,2.9,3.4,3.2,3.8,3.6,4.1,4,4.6,4.9,5.6],c:[2.4,2.6,2.5,2.9,2.8,3.2,3.1,3.5,3.4,3.8,4,4.5]}};
const money=n=>'Rs '+Math.round(n).toLocaleString('en-US');
const kpi=(l,v,d,up,sp)=>`<div class="card p-5"><div class="flex justify-between items-start"><p class="text-sm text-mu">${l}</p>${spark(sp)}</div><p class="text-2xl font-bold mt-1">${v}</p><p class="text-xs mt-1 font-semibold ${up?'text-emerald-500':'text-rose-500'}">${d} <span class="text-mu font-medium">vs previous</span></p></div>`;
const orows=(lim)=>S.orders.filter(o=>(S.of=='All'||o[4]==S.of)&&(o.join(' ').toLowerCase().includes(S.q.toLowerCase()))).slice(0,lim||99).map(o=>`<tr><td class="font-semibold">${o[0]}</td><td>${o[1]}</td><td>${o[2]}</td><td>${o[5]}</td><td class="font-semibold">${o[3]}</td><td>${badge(o[4],sc[o[4]])}</td></tr>`).join('')||'<tr><td colspan="6" class="text-mu">No orders match. Clear the search or pick another status.</td></tr>';
const OH=['Order','Customer','Items','Area','Total','Status'];

const ms=(l,v,d)=>`<div class="card p-5"><p class="text-sm text-mu">${l}</p><p class="text-2xl font-bold mt-1">${v}</p><p class="text-xs text-mu mt-1">${d}</p></div>`;
const D={cf:'All',users:[['Ayesha Khan','Block 7',14,'Rs 186','VIP'],['Bilal Ahmed','Block 9',9,'Rs 92','Active'],['Sana Malik','Block 9',22,'Rs 310','VIP'],['Omar Farooq','Block 3',5,'Rs 41','Active'],['Hina Raza','Block 11',3,'Rs 28','Inactive'],['Zain Ali','Block 7',17,'Rs 204','VIP']],
prod:[['Basmati rice 5 kg','Staples',11.2,14.5,9.9,1],['Cooking oil 5 L','Oils',13.9,17.8,12.4,1],['Fresh eggs, 30 tray','Dairy and eggs',5.1,6.4,4.5,1],['Wheat flour 10 kg','Staples',8.4,10.9,7.5,1],['Pulses bundle','Staples',6.4,8.2,5.7,0],['Sugar 5 kg','Staples',4.9,6.1,4.3,1]],
pay:[['PAY-5021','Ayesha Khan','Card',42.1,'Paid','Oct 23'],['PAY-5020','Bilal Ahmed','Cash on delivery',8.4,'Pending','Oct 23'],['PAY-5019','Hina Raza','Card',13.9,'Refund requested','Oct 22'],['PAY-5018','Sana Malik','Wallet',10.2,'Paid','Oct 22'],['PAY-5017','Zain Ali','Card',22.4,'Paid','Oct 21'],['PAY-5016','Maryam Iqbal','Cash on delivery',17.6,'Pending','Oct 21']],
hoods:[['Block 3',180,2,96,62],['Block 7',320,4,210,88],['Block 9',275,3,170,74],['Block 11',210,2,120,55]],
set:{name:'Rashan Cart',email:'support@rashancart.example',fee:5,min:50,policy:'Full refund',n1:1,n2:1,n3:0}};
const V={
customers(){const f=D.cf;return head('Customers','People who join your neighborhood campaigns.',`<button class="btn btn-p flex items-center gap-1.5" onclick="toast('Invite link copied')">${ic('plus','w-4 h-4')}Invite customer</button>`)+`<div class="grid sm:grid-cols-3 gap-4 mb-4">${ms('Total customers','1,284','+96 this month')}${ms('VIP customers','118','Spend over Rs 200')}${ms('Repeat rate','72%','Joined 2 or more campaigns')}</div>`+card('All customers',`<div class="flex gap-2 mb-3">${['All','VIP','Active','Inactive'].map(x=>`<button class="chip ${x==f?'on':''}" onclick="D.cf='${x}';draw()">${x}</button>`).join('')}</div>`+table(['Customer','Area','Campaigns joined','Total savings','Status'],D.users.filter(u=>f=='All'||u[4]==f).map(u=>[`<div class="flex items-center gap-2.5"><span class="w-8 h-8 rounded-full bg-bs text-bt grid place-items-center text-xs font-bold">${u[0].split(' ').map(w=>w[0]).join('')}</span><b>${u[0]}</b></div>`,u[1],u[2],u[3],badge(u[4],{VIP:'b',Active:'g',Inactive:'x'}[u[4]])])))},
products(){return head('Products','Control what appears in campaigns and what each unit earns.',`<button class="btn btn-p flex items-center gap-1.5" onclick="toast('Product form coming soon')">${ic('plus','w-4 h-4')}Add product</button>`)+`<div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-4">${D.prod.map((p,i)=>`<div class="card p-5 ${p[5]?'':'opacity-60'}"><div class="flex justify-between items-start"><div class="w-10 h-10 rounded-xl bg-bs text-bt grid place-items-center">${ic('tag')}</div>${badge(p[5]?'Published':'Hidden',p[5]?'g':'x')}</div><p class="font-semibold mt-3">${p[0]}</p><p class="text-xs text-mu">${p[1]}</p><div class="flex items-end gap-2 mt-3"><span class="text-2xl font-bold">Rs ${p[2].toFixed(2)}</span><s class="text-sm text-mu pb-0.5">Rs ${p[3].toFixed(2)}</s></div><div class="grid grid-cols-2 gap-3 mt-4 text-xs"><div class="rounded-xl bg-bg p-2.5"><p class="text-mu">Customer saves</p><p class="font-bold text-sm text-emerald-500">${Math.round((p[3]-p[2])/p[3]*100)}%</p></div><div class="rounded-xl bg-bg p-2.5"><p class="text-mu">Your margin</p><p class="font-bold text-sm">${Math.round((p[2]-p[4])/p[2]*100)}%</p></div></div><button class="btn w-full mt-4" onclick="D.prod[${i}][5]^=1;draw()">${p[5]?'Hide from campaigns':'Publish'}</button></div>`).join('')}</div>`},
payments(){const sum=a=>D.pay.filter(p=>a.includes(p[4])).reduce((t,p)=>t+p[3],0),m=n=>'Rs '+n.toFixed(2),pc={Paid:'g',Pending:'a','Refund requested':'r',Refunded:'x'};
return head('Payments','Track collections, cash on delivery and refunds.')+`<div class="grid sm:grid-cols-3 gap-4 mb-4">${ms('Collected',m(sum(['Paid'])),'Card and wallet')}${ms('Pending',m(sum(['Pending'])),'Cash on delivery')}${ms('Refunds',m(sum(['Refund requested','Refunded'])),'Requested and paid out')}</div>`+card('Transactions',table(['Payment','Customer','Method','Amount','Date','Status','Action'],D.pay.map((p,i)=>[`<b>${p[0]}</b>`,p[1],p[2],m(p[3]),p[5],badge(p[4],pc[p[4]]),p[4]=='Refund requested'?`<button class="btn btn-p" onclick="D.pay[${i}][4]='Refunded';draw();toast('Refund approved')">Approve refund</button>`:p[4]=='Pending'?`<button class="btn" onclick="D.pay[${i}][4]='Paid';draw();toast('Marked as paid')">Mark paid</button>`:'<span class="text-mu text-xs">No action</span>'])))},
neighborhoods(){return head('Neighborhoods','Where demand is growing and where to launch next.',`<button class="btn btn-p flex items-center gap-1.5" onclick="toast('Neighborhood added')">${ic('plus','w-4 h-4')}Add neighborhood</button>`)+`<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4">${D.hoods.map(h=>`<div class="card p-5"><div class="w-10 h-10 rounded-xl bg-bs text-bt grid place-items-center">${ic('pin')}</div><p class="font-semibold mt-3">${h[0]}</p><p class="text-xs text-mu">${h[1]} households</p><div class="flex justify-between text-sm mt-4"><span class="text-mu">Campaigns</span><b>${h[2]}</b></div><div class="flex justify-between text-sm mt-1"><span class="text-mu">Orders per week</span><b>${h[3]}</b></div><div class="mt-3">${prog(h[4])}</div><p class="text-xs text-mu mt-1">${h[4]}% of households ordering</p></div>`).join('')}</div><div class="mt-4">${card('Orders per week by area',bars(D.hoods.map(h=>h[3]),D.hoods.map(h=>h[0])))}</div>`},
settings(){const T=(k,t,d)=>`<div class="flex items-center justify-between gap-4 py-3 border-t border-bd"><div><p class="text-sm font-semibold">${t}</p><p class="text-xs text-mu">${d}</p></div><button role="switch" aria-checked="${!!D.set[k]}" aria-label="${t}" onclick="D.set.${k}^=1;draw()" class="w-11 h-6 rounded-full relative shrink-0" style="background:${D.set[k]?'var(--br)':'var(--bd)'}"><i class="absolute top-0.5 w-5 h-5 rounded-full bg-white" style="left:${D.set[k]?'22px':'2px'}"></i></button></div>`;
const F=(l,k,t='text')=>`<label class="block text-xs text-mu">${l}<input type="${t}" value="${D.set[k]}" oninput="D.set.${k}=this.value" class="mt-1"></label>`;
return head('Settings','Business details, pricing rules and alerts.',`<button class="btn btn-p" onclick="toast('Settings saved')">Save changes</button>`)+`<div class="grid xl:grid-cols-2 gap-4">${card('Business profile',`<div class="space-y-3">${F('Business name','name')}${F('Support email','email','email')}</div>`)}${card('Pricing and campaign rules',`<div class="space-y-3">${F('Service fee (%)','fee','number')}${F('Default minimum target (units)','min','number')}<label class="block text-xs text-mu">If a campaign misses its target<select class="mt-1" onchange="D.set.policy=this.value">${['Full refund','Offer alternative price','Extend deadline'].map(o=>`<option ${o==D.set.policy?'selected':''}>${o}</option>`).join('')}</select></label></div>`)}${card('Notifications',T('n1','Campaign ready','Alert me when a campaign reaches its target')+T('n2','Low stock','Alert me when stock drops below the minimum')+T('n3','Delivery delays','Alert me when a delivery runs late'),'','xl:col-span-2')}</div>`},

dashboard(){const R=RG[S.range],k=R.m;
 const ready=S.camps.filter(c=>st(c)=='Ready').length;
 return head('Good morning, Admin','Here is what is happening across your neighborhoods today.',['7d','30d','90d'].map(r=>`<button class="chip ${r==S.range?'on':''}" onclick="S.range='${r}';draw()">${r=='7d'?'Last 7 days':r=='30d'?'Last 30 days':'Last 90 days'}</button>`).join('')+`<button class="btn btn-p flex items-center gap-1.5" onclick="newCamp()">${ic('plus','w-4 h-4')}New campaign</button>`)+
 `<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4">${kpi('Revenue',money(38240*k),'+12.4%',1,[3,4,3.5,5,4.6,6,5.8])}${kpi('Procurement cost',money(29870*k),'+9.1%',0,[3,3.4,3.2,4,3.9,4.5,4.4])}${kpi('Net profit',money(5910*k),'+21.3%',1,[1,1.2,1.1,1.6,1.5,2,2.2])}${kpi('Orders',Math.round(412*k).toLocaleString(),'+8.0%',1,[5,6,5.5,7,6.4,8,8.4])}</div>`+
 `<div class="grid xl:grid-cols-3 gap-4 mt-4">${card('Revenue vs procurement cost',area([{v:R.r,c:'#3fcf80'},{v:R.c,c:'#f5b83d'}],R.l),'<div class="flex gap-4 text-xs text-mu"><span class="flex items-center gap-1.5"><i class="w-2.5 h-2.5 rounded-full" style="background:#3fcf80"></i>Revenue</span><span class="flex items-center gap-1.5"><i class="w-2.5 h-2.5 rounded-full" style="background:#f5b83d"></i>Cost</span></div>','xl:col-span-2')}${card('Sales by category',donut([['Staples',38],['Dairy and eggs',24],['Oils',20],['Beverages',11],['Other',7]]))}</div>`+
 `<div class="grid xl:grid-cols-3 gap-4 mt-4">${card('Campaign progress',S.camps.slice(0,5).map(c=>`<div class="py-2.5 flex items-center gap-4"><div class="w-40 min-w-0"><p class="text-sm font-semibold truncate">${c.n}</p><p class="text-xs text-mu">${c.h} · ends ${c.d}</p></div><div class="flex-1">${prog(c.j/c.t*100)}</div><span class="text-xs text-mu w-14 text-right">${c.j}/${c.t}</span>${badge(st(c),stc[st(c)])}</div>`).join(''),`<button class="btn" onclick="go('campaigns')">View all</button>`,'xl:col-span-2')}${card('Activity',[['Campaign “Eggs” hit its target','2 min ago','g'],['Al-Noor sent a rice quote of Rs 10.80','18 min ago','b'],['Refund requested on order #1084','1 h ago','r'],['Stock received: sugar x90','3 h ago','g'],['Rider Kamran reported a delay','5 h ago','a']].map(a=>`<div class="flex gap-3 py-2"><span class="mt-1.5 w-2 h-2 rounded-full shrink-0" style="background:${{g:'#10b981',b:'#3b82f6',r:'#f43f5e',a:'#f59e0b'}[a[2]]}"></span><div><p class="text-sm">${a[0]}</p><p class="text-xs text-mu">${a[1]}</p></div></div>`).join(''))}</div>`+
 `<div class="grid xl:grid-cols-3 gap-4 mt-4">${card('Supplier quotes: rice 5 kg',S.sup.slice(0,3).map((s,i)=>`<div class="flex items-center justify-between py-2.5 ${i?'border-t border-bd':''}"><div><p class="text-sm font-semibold">${s[0]}</p><p class="text-xs text-mu">Rating ${s[1]} · ${s[2]}% on time</p></div><div class="text-right"><p class="font-bold">${['Rs 10.80','Rs 11.30','Rs 11.90'][i]}</p>${i==0?badge('Best price'):''}</div></div>`).join(''))}${card('Low stock',S.stock.filter(x=>x[1]<x[2]).map(x=>`<div class="py-2"><div class="flex justify-between text-sm mb-1.5"><span class="font-medium">${x[0]}</span><span class="text-rose-500 font-semibold">${x[1]} left</span></div>${prog(x[1]/x[2]*100,'#f43f5e')}</div>`).join(''),`<button class="btn" onclick="go('inventory')">Manage</button>`)}${card('Delivery status',`<div class="flex h-3 rounded-full overflow-hidden"><i style="width:62%;background:#10b981"></i><i style="width:24%;background:#3b82f6"></i><i style="width:9%;background:#f59e0b"></i><i style="width:5%;background:#f43f5e"></i></div><div class="grid grid-cols-2 gap-3 mt-4 text-sm">${[['Delivered','62%','#10b981'],['On the way','24%','#3b82f6'],['Pending','9%','#f59e0b'],['Delayed','5%','#f43f5e']].map(x=>`<div class="flex items-center gap-2"><i class="w-2.5 h-2.5 rounded-full" style="background:${x[2]}"></i>${x[0]}<b class="ml-auto">${x[1]}</b></div>`).join('')}</div><p class="text-xs text-mu mt-4">3 riders active · average 11 minutes per stop</p>`)}</div>`+
 `<div class="mt-4">${card('Recent orders',table(OH,[]).replace('<tbody >','<tbody>').replace('</tbody>',orows(5)+'</tbody>'),`<button class="btn" onclick="go('orders')">View all</button>`)}</div>`},
campaigns(){return head('Campaigns','Create campaigns, watch demand, and confirm bulk purchases.',`<button class="btn btn-p flex items-center gap-1.5" onclick="newCamp()">${ic('plus','w-4 h-4')}New campaign</button>`)+
 card('All campaigns',table(['Campaign','Area','Ends','Progress','Units','Status','Action'],S.camps.map((c,i)=>[`<b>${c.n}</b>`,c.h,c.d,prog(c.j/c.t*100),`${c.j}/${c.t}`,badge(st(c),stc[st(c)]),st(c)=='Ready'?`<button class="btn btn-p" onclick="S.camps[${i}].s='Ordered';draw();toast('Bulk purchase order created')">Create purchase order</button>`:st(c)=='Open'?`<button class="btn" onclick="S.camps[${i}].s='Closed';draw();toast('Campaign closed. Refund policy applied')">Close</button>`:'<span class="text-mu text-xs">No action</span>']))) },
orders(){return head('Orders','Search, filter and manage every customer order.')+card('All orders',`<div class="flex flex-wrap gap-2 mb-3">${['All','Pending','Delivering','Delivered','Refund'].map(f=>`<button class="chip ${f==S.of?'on':''}" onclick="S.of='${f}';draw()">${f}</button>`).join('')}<input class="!w-56 ml-auto" placeholder="Filter orders" value="${S.q}" oninput="S.q=this.value;$('#ob').innerHTML=orows()"></div>`+table(OH,'','ob').replace('<tbody id="ob">','<tbody id="ob">'+orows()))},
suppliers(){return head('Suppliers','Compare quotes and watch supplier performance.')+`<div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4">${S.sup.map(s=>`<div class="card p-5"><div class="w-10 h-10 rounded-xl bg-bs text-bt grid place-items-center">${ic('bld')}</div><p class="font-semibold mt-3">${s[0]}</p><p class="text-xs text-mu">${s[3]}</p><div class="flex justify-between text-sm mt-4"><span class="text-mu">Rating</span><b>${s[1]}</b></div><div class="mt-2">${prog(s[2])}</div><p class="text-xs text-mu mt-1">${s[2]}% on-time delivery</p></div>`).join('')}</div><div class="mt-4">${card('Open quotation requests',table(['Product','Qty','Needed by','Quotes in','Best quote','Action'],[['Basmati rice 5 kg','100','Oct 28','3','Rs 10.80 · Al-Noor','<button class="btn btn-p" onclick="toast(\'Quote accepted: Al-Noor Traders\')">Accept best</button>'],['Cooking oil 5 L','80','Oct 30','2','Rs 13.20 · City Wholesale','<button class="btn btn-p" onclick="toast(\'Quote accepted: City Wholesale\')">Accept best</button>'],['Pulses bundle','70','Oct 29','1','Rs 6.40 · Metro Foods','<button class="btn" onclick="toast(\'Reminder sent to suppliers\')">Ask for more</button>']]))}</div>`},
inventory(){return head('Inventory','Track stock levels and reorder before you run out.')+card('Stock levels',table(['Product','Supplier','In stock','Minimum','Level','Status','Action'],S.stock.map((x,i)=>{const low=x[1]<x[2];return [`<b>${x[0]}</b>`,x[3],x[1],x[2],prog(x[1]/(x[2]*2)*100,low?'#f43f5e':'var(--br)'),badge(low?'Low':'Healthy',low?'r':'g'),low?`<button class="btn btn-p" onclick="S.stock[${i}][1]+=${x[2]};draw();toast('Reorder placed: ${x[0]}')">Reorder</button>`:'<span class="text-mu text-xs">Not needed</span>']})))},
deliveries(){return head('Deliveries','Assign riders and follow progress.')+`<div class="grid md:grid-cols-3 gap-4">${S.riders.map(r=>`<div class="card p-5"><div class="flex items-center gap-3"><div class="w-10 h-10 rounded-full bg-bs text-bt grid place-items-center font-bold">${r[0][0]}</div><div><p class="font-semibold">${r[0]}</p><p class="text-xs text-mu">${r[1]}</p></div></div><div class="mt-4">${prog(r[2]/r[3]*100)}</div><div class="flex justify-between text-xs text-mu mt-2"><span>${r[2]} of ${r[3]} delivered</span><span class="${r[4]?'text-amber-500':''}">${r[4]} delayed</span></div></div>`).join('')}</div><div class="mt-4">${card('Delayed deliveries',table(['Order','Customer','Rider','Delay','Action'],[['#1083','Zain Ali','Kamran Ali','25 min','<button class="btn" onclick="toast(\'Customer notified\')">Notify customer</button>'],['#1082','Maryam Iqbal','Saad Mehmood','40 min','<button class="btn" onclick="toast(\'Order reassigned\')">Reassign</button>'],['#1088','Ayesha Khan','Imran Siddiqui','15 min','<button class="btn" onclick="toast(\'Customer notified\')">Notify customer</button>']]))}</div>`},
reports(){return head('Reports','Profitability, savings and supplier performance.')+`<div class="grid xl:grid-cols-2 gap-4">${card('Profit by week',bars([3.1,3.8,4.2,4.9,4.6,5.9],['W1','W2','W3','W4','W5','W6'],'k'))}${card('Customer savings vs market',bars([18,21,22,20,23,22],['Rice','Oil','Flour','Eggs','Sugar','Pulses'],'%'))}${card('Campaign success rate',`<div class="flex items-center gap-6"><p class="text-5xl font-bold" style="color:var(--bt)">84%</p><p class="text-sm text-mu">of campaigns reached their bulk target in the last 90 days. 3 campaigns used the refund policy.</p></div><div class="mt-5">${prog(84)}</div>`)}${card('Cost breakdown',donut([['Procurement',78],['Delivery',12],['Refunds',4],['Packaging',4],['Other',2]]).replace('Rs 38.2k','Rs 29.9k').replace('Sales','Costs'))}</div>`}
};
function go(v){S.view=v;draw();scrollTo(0,0)}
function draw(){let g='';const n=NAV.map(x=>{const h=x[3]!=g?(g=x[3],`<p class="text-[11px] font-semibold text-mu px-3 pt-4 pb-1">${x[3]}</p>`):'';return h+`<button class="nav ${x[0]==S.view?'on':''}" onclick="go('${x[0]}')">${ic(x[2])}${x[1]}</button>`}).join('');
 $('#nav').innerHTML=n;$('#mnav').innerHTML=NAV.map(x=>`<button class="chip ${x[0]==S.view?'on':''}" onclick="go('${x[0]}')">${x[1]}</button>`).join('');$('#view').innerHTML=V[S.view]()}
function gsearch(q){if(q.length>1){S.q=q;S.of='All';if(S.view!='orders'){S.view='orders';draw();$('#gs').focus()}else{$('#ob').innerHTML=orows()}}}
function newCamp(){$('#modal').innerHTML=`<div class="fixed inset-0 z-40 grid place-items-center p-4" style="background:#0008" onclick="if(event.target==this)$('#modal').innerHTML=''"><div class="pop card p-6 w-full max-w-md"><h2 class="font-bold text-lg">New campaign</h2><p class="text-sm text-mu mb-4">Customers can join once you publish it.</p><div class="space-y-3"><label class="block text-xs text-mu">Product<input id="cn" placeholder="e.g. Basmati rice 5 kg"></label><div class="grid grid-cols-2 gap-3"><label class="block text-xs text-mu">Target units<input id="ct" type="number" value="100"></label><label class="block text-xs text-mu">End date<input id="cd" placeholder="Nov 5"></label></div><label class="block text-xs text-mu">Neighborhood<select id="ch"><option>Block 3</option><option>Block 7</option><option>Block 9</option><option>Block 11</option></select></label></div><div class="flex justify-end gap-2 mt-5"><button class="btn" onclick="$('#modal').innerHTML=''">Cancel</button><button class="btn btn-p" onclick="addCamp()">Publish campaign</button></div></div></div>`}
function addCamp(){const n=$('#cn').value.trim();if(!n){$('#cn').style.borderColor='#f43f5e';return}S.camps.unshift({n,h:$('#ch').value,j:0,t:+$('#ct').value||50,d:$('#cd').value||'Nov 5',s:'Open'});$('#modal').innerHTML='';S.view='campaigns';draw();toast('Campaign published')}
$('#ics').innerHTML=ic('search','w-4 h-4');$('#icb').innerHTML=ic('bell','w-4 h-4');
$('#np').innerHTML='<p class="font-semibold text-sm mb-2">Notifications</p>'+['2 campaigns are ready for purchase orders','3 products are below minimum stock','Refund requested on order #1084'].map(t=>`<p class="text-sm py-2 border-t border-bd">${t}</p>`).join('');
$('#th').onclick=()=>{const d=document.documentElement,dk=d.dataset.theme?d.dataset.theme=='dark':matchMedia('(prefers-color-scheme:dark)').matches;d.dataset.theme=dk?'light':'dark'};
document.addEventListener('keydown',e=>{if(e.key=='/'&&!/INPUT|SELECT/.test(document.activeElement.tagName)){e.preventDefault();$('#gs').focus()}});
draw();
</script>
@endverbatim
</body>
</html>